  Lemma kd_blk : 0 <= B /\ 0 <= k /\ B + k <= aceil /\ ((B = 0 /\ k = 0) \/ (AIMG_TOP <= B /\ aapp B k /\ In (po, B, k) LB /\ 0 < k)).
  Proof.
    pose proof aceil_facts as (AF & _).
    destruct OB as [[-> ->]|[IN Kp]]; [lia|]. pose proof (ah_blocks H HH _ _ _ _ RH IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn in R1, R3, R4, R5, R7.
    split; [lia|]. split; [exact R3|]. split; [exact R5|]. right. auto.
  Qed.

  (* [comment removed for export] *)
  Lemma kd_xcr : forall SPo shi O n, cobj LB LF SPo shi O n -> 0 <= n -> SP <= SPo ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) Xa -> (O + n <= B \/ B + k <= O) ->
    xclient_range H LB SP (Xa ++ (B, B + k) :: (sh B, sh B + nsh k) :: XS) O n.
  Proof.
    intros SPo shi O n C Hn LE FA D. pose proof (capp_not_shadowland _ _ _ _ (cobj_capp H HH _ _ _ _ _ _ _ _ _ RH RF C)) as NS.
    pose proof kd_blk as (B0 & K0 & BK & _). pose proof (sh_ge_lowsh B B0) as L. pose proof aceil_facts as (AF & _).
    pose proof (sh_nsh_high B k B0 K0 ltac:(unfold AAPP_HI; lia)) as U.
    destruct (xclient_range_cobj H HH _ _ _ _ _ _ _ _ Xa XS O n RH RF C Hn LE FA FXS) as [CR FX]. apply Forall_app in FX. destruct FX as [F1 F2].
    split; [exact CR|]. apply Forall_app. split; [exact F1|]. constructor; [cbn [fst snd]; exact D|]. constructor; [| exact F2]. cbn [fst snd].
    clear - NS L U. destruct NS; [left| right]; lia.
  Qed.
