  (* [comment removed for export] *)
  Lemma kd_sv : forall ptr len, ASvOwn LB mA ptr len ->
    (1 <= len -> Forall (fun iv : Z * Z => ptr + len <= fst iv \/ snd iv <= ptr) Xa /\ (ptr + len <= B \/ B + k <= ptr)) -> ASvOwn LB mB ptr len.
  Proof.
    intros ptr len [Z0|(L1 & p & cs & IN & CC & AD)] M; [left; exact Z0| right]. split; [exact L1|]. exists p, cs. destruct (M L1) as [M1 M2].
    split; [exact IN|]. split.
    - eapply (kd_rw SP AAPP_HI ptr len); [apply cobj_of_aobj; eapply aobj_block; [exact IN| lia| lia]| lia| exact M1| exact M2| lia
        | cbn [cells_size csize]; rewrite Nat.add_0_r, Z2Nat.id by lia; lia| exact CC].
    - eapply kd_addr; [exact IN| exact M2| lia| exact AD].
  Qed.
  Lemma kd_hdr : forall h, HdrOwnA LB mA h ->
    (1 <= hv_ml h -> Forall (fun iv : Z * Z => hv_mp h + hv_ml h <= fst iv \/ snd iv <= hv_mp h) Xa /\ (hv_mp h + hv_ml h <= B \/ B + k <= hv_mp h)) ->
    (1 <= hv_tl h -> Forall (fun iv : Z * Z => hv_tp h + hv_tl h <= fst iv \/ snd iv <= hv_tp h) Xa /\ (hv_tp h + hv_tl h <= B \/ B + k <= hv_tp h)) ->
    HdrOwnA LB mB h.
  Proof. intros h (O1 & O2 & R1 & R2) M1 M2. split; [exact (kd_sv _ _ O1 M1)|]. split; [exact (kd_sv _ _ O2 M2)|]. split; [exact R1| exact R2]. Qed.

  (* [comment removed for export] *)
  Lemma kd_blkX : forall p A n, In (p, A, n) LB -> 0 < n -> (A + n <= B \/ B + k <= A) ->
    Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) Xa ->
    Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (Xa ++ (B, B + k) :: (sh B, sh B + nsh k) :: XS)
    /\ Forall (fun iv : Z * Z => sh A + nsh n <= fst iv \/ snd iv <= sh A) (Xa ++ (B, B + k) :: (sh B, sh B + nsh k) :: XS).
  Proof.
    intros p A n IN Np D FA.
    pose proof (ah_blocks H HH _ _ _ _ RH IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn in R1, R2, R3, R4, R5, R6, R7.
    pose proof (aapp_bounds _ _ R7 R3) as (A1 & A2 & A3 & A4 & A5). pose proof aceil_facts as (AF & _).
    pose proof (aapp_not_shadowland _ _ R7) as NS. pose proof (sh_ge_lowsh A ltac:(clear - A4; lia)) as L.
    pose proof (sh_nsh_high A n ltac:(clear - A4; lia) R3 ltac:(clear - A3; lia)) as U.
    pose proof kd_blk as (B0 & K0 & BK & CS). pose proof (sh_ge_lowsh B B0) as L0. pose proof (sh_nsh_high B k B0 K0 ltac:(clear - BK AF; unfold AAPP_HI; lia)) as U0.
    split.
    - apply Forall_app. split; [exact FA|]. constructor; [cbn [fst snd]; exact D|]. constructor.
      + cbn [fst snd]. clear - NS L0 U0. unfold ALOWSH_LO, AHI_LO in *. lia.
      + eapply (Forall_scratch H HH); [exact RF| eapply (fsobj_block H HH); [exact RH| exact IN]| exact R3| clear - A3; lia| exact R7| exact FXS].
    - apply Forall_app. split; [apply noshadow_avoid_sh; [exact NSA| clear - A4; lia| exact R3| clear - A3; lia]|].
      constructor; [| constructor].
      + cbn [fst snd]. destruct CS as [[-> ->]|(T1 & T3 & _)]; [right; clear - L; unfold ALOWSH_LO in L; lia|].
        pose proof (aapp_not_shadowland _ _ T3) as NS0. clear - NS0 L U. unfold ALOWSH_LO, AHI_LO in *. lia.
      + cbn [fst snd]. destruct CS as [[-> ->]|(_ & _ & INo & Kp)]; [right; change (nsh 0) with 0; pose proof (sh_mono 0 A ltac:(clear - A4; lia)); clear - H0; lia|].
        assert (NI : blk_id (p, A, n) <> blk_id (po, B, k)).
        { cbn. intros E. pose proof (nodup_blk_eq _ _ _ (ah_nodup H HH _ _ _ RH) IN INo ltac:(cbn; exact E)) as Q. injection Q. intros En EA. clear - D Np En EA. lia. }
        destruct (blocks_sh_disjoint H HH _ _ _ _ _ RH IN INo NI) as [K|K]; cbn in K; [left| right]; exact K.
      + eapply (Forall_scratch_sh H HH); [exact RF| eapply (fsobj_block H HH); [exact RH| exact IN]| exact R3| clear - A3; lia| exact R7| exact FXS].
  Qed.
End KD.

(* [comment removed for export] *)
Lemma blocks_apart : forall s LB m p1 A1 n1 p2 A2 n2,
  as_RHEAP H s LB m -> In (p1, A1, n1) LB -> In (p2, A2, n2) LB -> A1 <> A2 ->
  (A1 + n1 + 16 <= A2 \/ A2 + n2 + 16 <= A1) /\ (sh A1 + nsh n1 <= sh A2 \/ sh A2 + nsh n2 <= sh A1).
Proof.
  intros s LB m p1 A1 n1 p2 A2 n2 RH I1 I2 NE.
  assert (NI : blk_id (p1, A1, n1) <> blk_id (p2, A2, n2)).
  { cbn. intros E. pose proof (nodup_blk_eq _ _ _ (ah_nodup H HH _ _ _ RH) I1 I2 ltac:(cbn; exact E)) as Q. injection Q. intros _ EA _. exact (NE EA). }
  split.
  - destruct (ah_disj H HH _ _ _ _ _ RH I1 I2 NI) as [K|K]; cbn in K; [left| right]; exact K.
  - destruct (blocks_sh_disjoint H HH _ _ _ _ _ RH I1 I2 NI) as [K|K]; cbn in K; [left| right]; exact K.
Qed.

