Lemma rin_ivs_dec : forall X a, rin_ivs X a \/ ~ rin_ivs X a.
Proof.
  induction X as [|[l h] X IH]; intros a; cbn [rin_ivs fst snd]; [right; intros K; exact K|]. destruct (IH a) as [K|K]; [left; right; exact K|].
  destruct (Z_le_dec l a) as [H1|H1]; [destruct (Z_lt_dec a h) as [H2|H2]; [left; left; split; assumption| right; intros [Q|Q]; [apply H2; exact (proj2 Q)| exact (K Q)]]
                                    | right; intros [Q|Q]; [apply H1; exact (proj1 Q)| exact (K Q)]].
Qed.

